byte i;           // задаем переменную для цифровых выходов
byte LedMin = 2;  // первый пин со светодиодом
byte LedMax = 10; // последний пин со светодиодом

void setup() {
   // задаем пин со 2 по 10, как выход (OUTPUT)
   for(i=LedMin; i<=LedMax; i++) { pinMode(i, OUTPUT); }
}

void loop() {
   // последовательно зажигаем светодиоды со 2 по 10 пин
   for(i=LedMin; i<=LedMax; i++) {
      digitalWrite(i, HIGH);
      delay(50);
   }

   // последовательно гасим светодиоды с 10 по 2 пин
   for(i=LedMax; i>=LedMin; i--) {
      digitalWrite(i, LOW);
      delay(50);
   }
}
